package io.knowledgebrain.activity;
import org.junit.jupiter.api.Test;import java.util.*;import io.knowledgebrain.contracts.learning.roadmap.v1.*;import static org.junit.jupiter.api.Assertions.*;
class ActivityEventTest extends ActivityFixtures {
 @Test void allTwentyImmutableOwnerContractsHaveScopedHistoricalEntries()throws Exception{var space=id();for(var pair:ActivityEvent.TOPICS.entrySet()){var wire=wire(pair.getKey(),space);var e=ActivityEvent.decode(pair.getValue(),wire);assertEquals(pair.getKey(),e.kind());assertEquals(space,e.spaceId());assertEquals(1,e.sourceVersion());assertTrue(ActivityEvent.target(e));ActivityEvent.transport(pair.getValue(),wire,e.aggregateId().toString(),headers(e));var altered=new HashMap<>(headers(e));altered.put("trace_id","b".repeat(32));assertThrows(IllegalArgumentException.class,()->ActivityEvent.transport(pair.getValue(),wire,e.aggregateId().toString(),altered));assertThrows(IllegalArgumentException.class,()->ActivityEvent.transport(pair.getValue(),wire,id().toString(),headers(e)));}}
 @Test void invalidEnvelopeAndSourceBindingsNeverBecomeTimelineRows()throws Exception{var wire=wire("ROADMAP",id());var e=RoadmapEventEnvelopeV1.parseFrom(wire);for(var bad:List.of(e.toBuilder().setProducer("content-service"),e.toBuilder().setEventVersion(2),e.toBuilder().setSpaceId(UUID.randomUUID().toString()),e.toBuilder().setTraceId("0".repeat(32)),e.toBuilder().setAggregateType("StudySession"),e.toBuilder().setAggregateId(id().toString()),e.toBuilder().setEventType("Unexpected"))){assertThrows(IllegalArgumentException.class,()->ActivityEvent.decode(ActivityEvent.TOPICS.get("ROADMAP"),bad.build().toByteArray()));}var p=RoadmapChangedPayloadV1.parseFrom(e.getPayload());for(var bad:List.of(p.toBuilder().setVisibility("PUBLIC"),p.toBuilder().setVersion(0),p.toBuilder().setRevisionId("spoof"))){assertThrows(IllegalArgumentException.class,()->ActivityEvent.decode(ActivityEvent.TOPICS.get("ROADMAP"),e.toBuilder().setPayload(bad.build().toByteString()).build().toByteArray()));}assertThrows(IllegalArgumentException.class,()->ActivityEvent.decode("other.topic",wire));assertThrows(IllegalArgumentException.class,()->ActivityEvent.decode(ActivityEvent.TOPICS.get("ROADMAP"),new byte[1048577]));}
 @Test void recoveryGapRequiresCanonicalRecoveryAndHttpOriginsStayFixed(){assertTrue(ActivityConsumer.gap(null,1,2));assertTrue(ActivityConsumer.gap(1L,2,3));assertTrue(ActivityConsumer.gap(4L,0,3));assertFalse(ActivityConsumer.gap(null,0,3));assertFalse(ActivityConsumer.gap(2L,0,3));for(String bad:List.of("http://localhost","https://a@localhost","https://localhost/path","https://localhost/?x=1","https://localhost/#fragment"))assertThrows(IllegalArgumentException.class,()->ActivityHttp.origin(bad));}
}
